*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
/* ⚠ v5.3 — 버튼·입력창은 기본이 Arial이라 앱 폰트를 상속하지 않는다.
     전수조사에서 160개 넘는 요소가 Arial로 렌더되고 있었다(한글은 맑은고딕 폴백).
     한 줄로 전 화면 서체가 통일된다. 개별 규칙의 font-family:inherit 은 이제 불필요.
     ⚠ font-size는 상속시키지 말 것 — 크기를 지정하지 않은 버튼이 커져 레이아웃이 밀린다. */
button,input,select,textarea{font-family:inherit}
button{cursor:pointer}
/* 이모지는 플랫폼 컬러 이모지 폰트를 명시해야 흑백·두부(□)로 깨지지 않는다 */
.emo,.cg i,.sec-tools button i,.gh-i,.tile i{font-family:"Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif}

.tile.sm i{font-size:19px} .tile.sm b{font-size:12.5px} .tile.sm s{font-size:10px}
/* ⚠ v5.3 — flex 2열 고정이라 도구가 3개면 마지막 하나만 전체폭으로 늘어나 균형이 깨졌다.
     개수에 맞춰 열 수를 정하는 grid 로. (n1/n3 은 렌더러가 붙여 준다) */
.sec-tools{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;padding:12px 16px 2px}
.sec-tools.n1{grid-template-columns:1fr}
.sec-tools.n3{grid-template-columns:repeat(3,1fr);gap:7px}
.sec-tools.n3 button{flex-direction:column;gap:4px;font-size:12px;padding:11px 4px}
.sec-tools button{display:flex;align-items:center;gap:7px;justify-content:center;min-width:0;

/* ⚠ v5.3 — 「‹」 하나뿐이라 실제 탭 영역이 8×24px 이었다(손가락으로 누르기 어려움).
     글자는 그대로 두고 히트박스만 40×40 으로 넓힌다. */
.top .back{font-size:24px;color:var(--ink);background:none;border:none;line-height:1;
  width:40px;height:40px;margin-left:-9px;display:flex;align-items:center;justify-content:center;border-radius:12px}
.top .back:active{background:var(--soft)}

/* ⚠ v5.3 — flex+min-width:60px 이라 「뜻 맞히기」 같은 긴 라벨이 2줄로 접혀
     행 높이가 55px / 77px 로 들쭉날쭉했다. 균등 grid + 라벨 길이에 따라 열 수를 자동 결정. */
.seg{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.seg.c2{grid-template-columns:repeat(2,1fr)}
.seg.c3{grid-template-columns:repeat(3,1fr)}
.seg.c5{grid-template-columns:repeat(5,1fr);gap:6px}
.seg button{min-width:0;padding:14px 4px;border:1.5px solid var(--line);border-radius:14px;background:#fff;
  font-weight:800;font-size:15px;color:var(--sub);transition:.15s;white-space:nowrap;
  overflow:hidden;text-overflow:ellipsis;line-height:1.25}
.seg.c5 button{font-size:14px}
.seg button.on{border-color:var(--ink);color:#fff;background:var(--ink);box-shadow:0 2px 6px rgba(43,39,35,.18)}

/* ⚠ v5.3 — bt/ba/bd/rd-prog 가 전부 <span>(inline)이라 제목·원제·소개·진도바가
     한 줄로 이어 흐르고 진도바는 아예 안 보였다. 반드시 block 으로 쌓는다. */
.rd-book .bt,.rd-book .ba,.rd-book .bd{display:block}
.rd-book .bt{font-size:16px;font-weight:800;line-height:1.3;letter-spacing:-.3px}
.rd-book .ba{font-size:11.5px;color:var(--sub);margin-top:3px;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rd-book .bd{font-size:12px;color:var(--sub);margin-top:5px;line-height:1.5;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}

/* ⚠ v5.3 — 가운데 정렬 flex-wrap 이라 2번째 줄이 들쭉날쭉하고
     짝이어야 할 「가﹣ / 가﹢」가 서로 다른 줄로 찢어졌다. 좌정렬 + 스테퍼 묶음. */
.rd-tools{display:flex;gap:6px;justify-content:flex-start;align-items:center;flex-wrap:wrap;padding:10px 16px 4px}
.rd-fs{display:inline-flex;gap:0;margin-left:auto;border:1px solid var(--line);border-radius:16px;overflow:hidden;background:var(--card)}
.rd-fs button{border:none!important;border-radius:0!important;padding:7px 12px}
.rd-fs button+button{border-left:1px solid var(--line)!important}

/* ⚠ v5.3 — tt/ds 가 <span>(inline)이라 게임 이름과 설명이 한 줄로 이어 붙었다
     (「타임어택 60초60초 안에 몇 점?…」). 읽기 목록(.rd-book)과 같은 사고. */
.gh-card .tt,.gh-card .ds{display:block}
.gh-card .tt{font-size:15.5px;font-weight:800;letter-spacing:-.3px}
.gh-card .ds{font-size:12px;color:var(--sub);margin-top:3px;line-height:1.45}

/* ⚠ v5.3 — overflow-x:auto 인데 6개 버튼이 32px 넘쳐 목록 한가운데 가로 스크롤바가 보였다.
     6열 grid 한 줄로 정리한다. */
.rd-filter{display:grid;grid-template-columns:repeat(6,1fr);gap:5px;padding:12px 16px 2px}
.rd-filter button{min-width:0;padding:8px 2px;border:1px solid var(--line);background:var(--card);
  border-radius:16px;font-size:12.5px;font-weight:800;color:var(--ink);white-space:nowrap;overflow:hidden}

